from __future__ import annotations

import os
from dataclasses import dataclass

from dotenv import load_dotenv

load_dotenv()


def _flag(name: str) -> bool:
    return os.environ.get(name, "0").strip().lower() in {"1", "true", "yes"}


@dataclass(frozen=True)
class Settings:
    openai_api_key: str
    neatlogs_api_key: str
    crustdata_api_key: str
    model: str
    workflow: str
    fault_inject: bool

    @classmethod
    def from_env(cls) -> Settings:
        return cls(
            openai_api_key=os.environ.get("OPENAI_API_KEY", ""),
            neatlogs_api_key=os.environ.get("NEATLOGS_API_KEY", ""),
            crustdata_api_key=os.environ.get("CRUSTDATA_API_KEY", "") or os.environ.get("CRUSTDATA_API_TOKEN", ""),
            model=os.environ.get("OURO_MODEL", "gpt-4o"),
            workflow=os.environ.get("OURO_WORKFLOW", "ouroboros-worker"),
            fault_inject=_flag("OURO_FAULT_INJECT"),
        )


settings = Settings.from_env()

from __future__ import annotations

from .config import settings


def init_tracing(run_id: str):
    if not settings.neatlogs_api_key:
        return None
    import neatlogs

    return neatlogs.init(api_key=settings.neatlogs_api_key, tags=[settings.workflow, f"run:{run_id}"])


def shutdown_tracing(tracker) -> None:
    if tracker is not None:
        tracker.shutdown()

from __future__ import annotations

import time
from typing import Any

import httpx

from ..config import settings

BASE_URL = "https://api.crustdata.com"
API_VERSION = "2025-11-01"


class CrustdataError(RuntimeError):
    def __init__(self, message: str, status: int | None = None, body: str = "") -> None:
        super().__init__(message)
        self.status = status
        self.body = body


class CrustdataClient:
    def __init__(self, token: str | None = None, http: httpx.Client | None = None) -> None:
        self.token = token if token is not None else settings.crustdata_api_key
        self.fault_inject = settings.fault_inject
        self.calls: list[dict[str, Any]] = []
        self._http = http

    def _client(self) -> httpx.Client:
        if self._http is not None:
            return self._http
        return httpx.Client(base_url=BASE_URL, timeout=30.0)

    def _headers(self) -> dict[str, str]:
        return {
            "authorization": f"Bearer {self.token}",
            "content-type": "application/json",
            "x-api-version": API_VERSION,
        }

    def post(self, path: str, payload: dict[str, Any]) -> dict[str, Any]:
        started = time.monotonic()
        record: dict[str, Any] = {"path": path, "payload_keys": sorted(payload), "status": None, "error": None}
        self.calls.append(record)
        try:
            self._maybe_inject_fault(path)
            owns_client = self._http is None
            http = self._client()
            try:
                response = http.post(path, json=payload, headers=self._headers())
            finally:
                if owns_client:
                    http.close()
            record["status"] = response.status_code
            if response.status_code >= 400:
                record["error"] = response.text[:300]
                raise CrustdataError(f"{path} -> HTTP {response.status_code}", status=response.status_code, body=response.text[:300])
            record["latency_ms"] = round((time.monotonic() - started) * 1000)
            return response.json()
        except CrustdataError:
            raise
        except httpx.HTTPError as exc:
            record["error"] = str(exc)
            raise CrustdataError(str(exc)) from exc

    def _maybe_inject_fault(self, path: str) -> None:
        if not self.fault_inject:
            return
        seen = sum(1 for c in self.calls if c["path"] == path)
        if seen <= 1:
            record = self.calls[-1]
            record["status"] = 429
            record["error"] = "rate_limited (injected)"
            raise CrustdataError("rate_limited (injected)", status=429, body="injected 429 for demo")

    def identify(self, domain: str) -> dict[str, Any]:
        return self.post("/company/identify", {"domains": [domain]})

    def enrich(self, company_id: str | None = None, domain: str | None = None) -> dict[str, Any]:
        if company_id:
            return self.post("/company/enrich", {"company_id": company_id})
        return self.post("/company/enrich", {"domains": [domain]})

    def search_people(self, company_id: str, limit: int = 10) -> dict[str, Any]:
        return self.post(
            "/person/search",
            {"filters": [{"filter_type": "COMPANY_ID", "type": "in", "value": [company_id]}], "page": 1, "limit": limit},
        )

    def web_search(self, query: str) -> dict[str, Any]:
        return self.post("/web/search/live", {"query": query})

    def account_endpoints(self) -> dict[str, Any]:
        return self.post("/account/endpoints", {})

from __future__ import annotations

import json
import time
import uuid
from pathlib import Path
from typing import Any

from ..config import settings
from ..state import append_run
from ..tools.crustdata import CrustdataClient, CrustdataError

DOSSIER_SECTIONS = ["overview", "people", "recent_news", "risks", "outreach_angles"]

TOOLS: list[dict[str, Any]] = [
    {
        "type": "function",
        "function": {
            "name": "identify_company",
            "description": "Resolve a company domain to a Crustdata company_id.",
            "parameters": {
                "type": "object",
                "properties": {"domain": {"type": "string"}},
                "required": ["domain"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "enrich_company",
            "description": "Fetch a full company profile. Provide company_id (preferred) or domain.",
            "parameters": {
                "type": "object",
                "properties": {
                    "company_id": {"type": "string"},
                    "domain": {"type": "string"},
                },
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "search_people",
            "description": "Find key people at a company by its company_id.",
            "parameters": {
                "type": "object",
                "properties": {"company_id": {"type": "string"}, "limit": {"type": "integer"}},
                "required": ["company_id"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "web_search",
            "description": "Search the live web for recent news, reviews, or context about a company.",
            "parameters": {
                "type": "object",
                "properties": {"query": {"type": "string"}},
                "required": ["query"],
            },
        },
    },
]

_SYSTEM = (
    "You are the Ouroboros research worker. You produce verified company dossiers from a domain. "
    "Use the provided tools to gather evidence, then answer with a single JSON object (no markdown fences) "
    "with exactly these keys: domain, overview, people, recent_news, risks, outreach_angles. "
    "Every factual claim must come from tool results. If a tool fails, note it and continue with the other tools."
)


def _llm():
    from openai import OpenAI

    return OpenAI(api_key=settings.openai_api_key)


def _dispatch(name: str, args: dict[str, Any], client: CrustdataClient) -> dict[str, Any]:
    if name == "identify_company":
        return client.identify(args["domain"])
    if name == "enrich_company":
        return client.enrich(company_id=args.get("company_id"), domain=args.get("domain"))
    if name == "search_people":
        return client.search_people(args["company_id"], limit=int(args.get("limit", 10)))
    if name == "web_search":
        return client.web_search(args["query"])
    raise ValueError(f"unknown tool: {name}")


def parse_json_object(text: str) -> dict[str, Any]:
    cleaned = (text or "").strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`")
        if cleaned.startswith("json"):
            cleaned = cleaned[4:]
    start = cleaned.find("{")
    end = cleaned.rfind("}")
    if start == -1 or end == -1:
        return {}
    try:
        data = json.loads(cleaned[start : end + 1])
    except json.JSONDecodeError:
        return {}
    return data if isinstance(data, dict) else {}


def validate_dossier(dossier: dict[str, Any], evidence: dict[str, Any]) -> list[str]:
    issues: list[str] = []
    for section in DOSSIER_SECTIONS:
        value = dossier.get(section)
        if value is None or value == "" or value == [] or value == {}:
            issues.append(f"missing section: {section}")
    if not evidence.get("tools_succeeded"):
        issues.append("no successful tool calls in evidence")
    if not evidence.get("company_id"):
        issues.append("company never resolved via identify_company")
    return issues


def run_dossier(domain: str, out_root: Path | None = None) -> dict[str, Any]:
    run_id = uuid.uuid4().hex[:8]
    started = time.monotonic()
    out_root = out_root or Path(__file__).resolve().parent.parent.parent / "out"
    client = CrustdataClient()
    evidence: dict[str, Any] = {
        "domain": domain,
        "tool_results": {},
        "tools_succeeded": [],
        "tool_failures": [],
        "company_id": None,
    }

    llm = _llm()
    messages: list[dict[str, Any]] = [
        {"role": "system", "content": _SYSTEM},
        {"role": "user", "content": f"Build a dossier for: {domain}"},
    ]

    dossier: dict[str, Any] = {}
    steps = 0
    for _ in range(12):
        steps += 1
        resp = llm.chat.completions.create(model=settings.model, messages=messages, tools=TOOLS)
        msg = resp.choices[0].message
        messages.append(msg.model_dump(exclude_none=True))
        if not msg.tool_calls:
            dossier = parse_json_object(msg.content or "")
            break
        for call in msg.tool_calls:
            args = json.loads(call.function.arguments or "{}")
            try:
                result = _dispatch(call.function.name, args, client)
                evidence["tools_succeeded"].append(call.function.name)
                evidence["tool_results"][call.function.name] = result
                if call.function.name == "identify_company" and isinstance(result, dict):
                    evidence["company_id"] = _extract_company_id(result)
                payload = json.dumps(result, default=str)[:6000]
            except CrustdataError as exc:
                evidence["tool_failures"].append(
                    {"tool": call.function.name, "args": args, "status": exc.status, "error": str(exc)}
                )
                payload = json.dumps({"error": str(exc), "status": exc.status})
            messages.append({"role": "tool", "tool_call_id": call.id, "content": payload})

    schema_issues = validate_dossier(dossier, evidence)
    verdict = _verify(domain, dossier, evidence)
    passed = verdict.get("passed", False) and not schema_issues

    run_record: dict[str, Any] = {
        "run_id": run_id,
        "domain": domain,
        "status": "success" if passed else "failed",
        "duration_s": round(time.monotonic() - started, 2),
        "steps": steps,
        "tools_succeeded": sorted(set(evidence["tools_succeeded"])),
        "tool_failures": evidence["tool_failures"],
        "schema_issues": schema_issues,
        "verify_issues": verdict.get("issues", []),
        "llm_calls": len([m for m in messages if m.get("role") == "assistant"]),
        "tool_calls": client.calls,
    }

    out_dir = out_root / domain.replace(".", "_") / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / "dossier.json").write_text(json.dumps(dossier, indent=2, default=str))
    (out_dir / "run.json").write_text(json.dumps(run_record, indent=2, default=str))
    append_run(run_record)
    return run_record


def _extract_company_id(result: dict[str, Any]) -> str | None:
    for key in ("companies", "results", "data"):
        rows = result.get(key)
        if isinstance(rows, list) and rows and isinstance(rows[0], dict):
            return rows[0].get("company_id") or rows[0].get("id")
    return result.get("company_id") or result.get("id")


def _verify(domain: str, dossier: dict[str, Any], evidence: dict[str, Any]) -> dict[str, Any]:
    llm = _llm()
    prompt = (
        "Verify this dossier against the evidence. Reply with JSON only: "
        '{"passed": true|false, "issues": ["..."]}.\n'
        f"Domain: {domain}\nDossier: {json.dumps(dossier, default=str)[:4000]}\n"
        f"Tools that succeeded: {evidence['tools_succeeded']}\n"
        f"Tools that failed: {json.dumps(evidence['tool_failures'], default=str)[:1500]}"
    )
    resp = llm.chat.completions.create(
        model=settings.model,
        messages=[{"role": "user", "content": prompt}],
    )
    return parse_json_object(resp.choices[0].message.content or "")

from __future__ import annotations

import json
import subprocess
from typing import Any

from ..state import read_runs
from ..worker import run_dossier

REMEDIATIONS: dict[str, str] = {
    "429": "retry_with_backoff",
    "401": "refresh_credentials",
    "403": "switch_tool_alternate_endpoint",
    "404": "revise_plan_skip_step",
    "verify_failed": "revise_synthesis_prompt",
    "missing_section": "revise_synthesis_prompt",
    "no_evidence": "revise_plan_expand_search",
}


def classify_run(run: dict[str, Any]) -> list[str]:
    reasons: list[str] = []
    for failure in run.get("tool_failures", []):
        status = failure.get("status")
        if status:
            reasons.append(str(status))
        else:
            reasons.append("network_error")
    if run.get("status") != "success":
        if run.get("verify_issues"):
            reasons.append("verify_failed")
        if run.get("schema_issues"):
            reasons.append("missing_section")
        if not run.get("tools_succeeded"):
            reasons.append("no_evidence")
    out: list[str] = []
    for reason in reasons:
        if reason not in out:
            out.append(reason)
    return out


def plan_remediation(run: dict[str, Any]) -> dict[str, Any]:
    reasons = classify_run(run)
    actions = [REMEDIATIONS.get(r, "manual_review") for r in reasons]
    return {"run_id": run.get("run_id"), "domain": run.get("domain"), "reasons": reasons, "actions": actions}


def failed_runs(window_hours: float | None = None) -> list[dict[str, Any]]:
    runs = [r for r in read_runs() if r.get("status") != "success"]
    if window_hours is not None:
        import time

        cutoff = time.time() - window_hours * 3600
        runs = [r for r in runs if r.get("started_epoch", 0) >= cutoff]
    return runs


def read_recent_traces(limit: int = 5) -> list[dict[str, Any]]:
    try:
        proc = subprocess.run(
            ["neatlogs", "traces", "list", "--limit", str(limit), "--json"],
            capture_output=True,
            text=True,
            timeout=60,
        )
    except (OSError, subprocess.TimeoutExpired):
        return []
    if proc.returncode != 0:
        return []
    try:
        data = json.loads(proc.stdout)
    except json.JSONDecodeError:
        return []
    return data if isinstance(data, list) else data.get("traces", [])


def supervise(window_hours: float | None = None, rerun: bool = True) -> list[dict[str, Any]]:
    reports: list[dict[str, Any]] = []
    for run in failed_runs(window_hours):
        report = plan_remediation(run)
        traces = read_recent_traces()
        report["trace_count_seen"] = len(traces)
        if rerun:
            report["rerun"] = run_dossier(run["domain"])
        reports.append(report)
    return reports

